    scissors:
      '<circle cx="6" cy="6" r="3"/><circle cx="6" cy="18" r="3"/><line x1="20" y1="4" x2="8.12" y2="15.88"/><line x1="14.47" y1="14.48" x2="20" y2="20"/><line x1="8.12" y1="8.12" x2="12" y2="12"/>',
    // ícone de pino/fixar, usado no botão do canto do carrossel
    // Hoje/Recorde pra travar o slide atual (parar de girar sozinho).
    pin: '<path d="M12 2a5 5 0 0 0-5 5c0 3 2 4 2 7h6c0-3 2-4 2-7a5 5 0 0 0-5-5z"/><line x1="12" y1="14" x2="12" y2="22"/>',
    // usado no link "Abrir página da extensão" (fallback manual do aviso
