  // Checagem silenciosa automática — no máximo uma vez a cada 24h, e só
  // mostra popup se realmente houver versão mais nova (sem incomodar o
  // usuário quando já está atualizado).
  function verificarAtualizacaoAutomaticamente() {
    // interruptor em "Opções gerais" — se o usuário desligou a
    // notificação automática, não faz a checagem silenciosa (a checagem
    // manual pelo menu continua funcionando normalmente).
    if (!isAutoUpdateNotificacaoAtiva()) return;

    const ultima = GM_getValue(STORAGE_ULTIMA_CHECAGEM_KEY, 0);
    const UM_DIA_MS = 24 * 60 * 60 * 1000;
    if (mxmAgoraMs() - ultima < UM_DIA_MS) return;

    verificarAtualizacao((resultado) => {
      if (resultado && !resultado.erro && resultado.temAtualizacao) {
        mostrarPopupAtualizacaoDisponivel(resultado.versaoRemota, resultado.notas);
      }
    });
  }

  // ---------- Config: mostrar/esconder número no ícone (bolha verde) ----------

  function isBadgeVisible() {
    // padrão: visível, a menos que o usuário tenha desligado explicitamente
    return localStorage.getItem(STORAGE_BADGE_KEY) !== '0';
  }

  function setBadgeVisible(value) {
    localStorage.setItem(STORAGE_BADGE_KEY, value ? '1' : '0');
  }

  // ---------- ordenar/filtrar a lista principal (data/missão/A-Z) ----------

  const ORDENACOES_LOG_VALIDAS = ['data', 'missao', 'alfabetica'];

  function getOrdenacaoLog() {
    const valor = localStorage.getItem(STORAGE_ORDENACAO_LOG_KEY);
    return ORDENACOES_LOG_VALIDAS.includes(valor) ? valor : 'data';
  }

  function setOrdenacaoLog(valor) {
    localStorage.setItem(STORAGE_ORDENACAO_LOG_KEY, ORDENACOES_LOG_VALIDAS.includes(valor) ? valor : 'data');
  }

  // Normaliza texto pra comparação alfabética (minúsculas, sem acento) —
  // mesma técnica de normalizeKey, só que sem juntar título+artista.
  function normalizarParaOrdenacao(texto) {
    return (texto || '')
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .trim();
  }

  // Reordena (e anota com _grupoChave/_grupoRotulo) as entradas já
  // filtradas pela busca, de acordo com o modo de ordenação atual. O
  // agrupamento visual (cabeçalhos "sticky" da lista) usa _grupoChave pra
  // decidir quando trocar de cabeçalho, e _grupoRotulo como texto do
  // cabeçalho — assim renderPainelLista não precisa saber os detalhes de
  // cada modo, só desenhar o que vier pronto aqui.
  function aplicarOrdenacaoEAgrupamento(entradas) {
    const modo = getOrdenacaoLog();
    const copia = entradas.slice();

    if (modo === 'missao') {
      copia.sort((a, b) => {
        const missaoA = a.missao || '';
        const missaoB = b.missao || '';
        if (!missaoA && missaoB) return 1;
        if (missaoA && !missaoB) return -1;
        if (missaoA !== missaoB) return missaoA.localeCompare(missaoB, 'pt');
        return b.timestamp - a.timestamp;
      });
      return copia.map((e) => ({
        ...e,
        _grupoChave: e.missao || '\u0000sem-missao',
        _grupoRotulo: e.missao || t('semMissaoLabel'),
      }));
    }

    if (modo === 'alfabetica') {
      copia.sort((a, b) => {
        const chaveA = normalizarParaOrdenacao(a.titulo);
        const chaveB = normalizarParaOrdenacao(b.titulo);
        if (chaveA !== chaveB) return chaveA.localeCompare(chaveB, 'pt');
        return b.timestamp - a.timestamp;
      });
      return copia.map((e) => {
        const primeiraLetra = normalizarParaOrdenacao(e.titulo).charAt(0).toUpperCase();
        return {
          ...e,
          _grupoChave: /[A-Z]/.test(primeiraLetra) ? primeiraLetra : '#',
          _grupoRotulo: /[A-Z]/.test(primeiraLetra) ? primeiraLetra : '#',
        };
      });
    }

    // modo === 'data' (padrão): mantém a ordem cronológica já vinda de
    // formatarEntradasOrdenadas (mais recente primeiro) e agrupa por dia.
    //
    // V2.NEW: as marcadas manualmente (e.origem === 'manual') saem dos
    // grupos por dia e formam sua própria categoria única no filtro —
    // pedido do usuário pra não misturar as duas origens dentro do mesmo
    // agrupamento por data. Elas mantêm a ordem cronológica entre si
    // (mais recente primeiro) e a categoria "Marcadas manualmente" fica
    // sempre por último, depois de todos os grupos de data — mesmo padrão
    // já usado pelo modo "missão" pra agrupar o que não se encaixa nos
    // grupos normais (ali é "sem missão", aqui é a origem manual).
    const automaticas = copia.filter((e) => e.origem !== 'manual');
    const manuais = copia.filter((e) => e.origem === 'manual');

    // V2.NEW: uma entrada enviada perto da virada de ciclo (21h de Brasília,
    // ver dataEfetivaParaCiclo) pode ter a MESMA data de calendário (e.data)
    // que outra enviada horas antes, mas pertencer a um CICLO DE MISSÃO
    // diferente (mês seguinte já começou pra fins de missão, calendário
    // ainda não virou). Sem isso, as duas apareciam misturadas sob o mesmo
    // cabeçalho de dia, como se fossem do mesmo ciclo. Aqui a gente separa
    // esse grupo de dia em sub-grupos por ciclo — só quando de fato há mais
    // de um ciclo presente no dia; na esmagadora maioria dos dias isso não
    // muda nada, o rótulo continua igual ao de sempre.
    const cicloPorEntradaAutomatica = new Map();
    automaticas.forEach((e) => {
      cicloPorEntradaAutomatica.set(e, chaveCicloDaEntrada(e));
    });

    const ciclosPorData = new Map();
    automaticas.forEach((e) => {
      const ciclo = cicloPorEntradaAutomatica.get(e);
      if (!ciclo) return; // sem timestamp confiável — não entra na contagem
      if (!ciclosPorData.has(e.data)) ciclosPorData.set(e.data, new Set());
      ciclosPorData.get(e.data).add(ciclo);
    });

    // Ordena as chaves "MM/YYYY" cronologicamente (ascendente) pra numerar
    // "Ciclo 1" = o mais antigo (mês que está terminando), "Ciclo 2" = o
    // mais novo (mês que já começou pra fins de missão).
    function ordemCronologicaChaveMesAno(chave) {
      const [mes, ano] = chave.split('/').map(Number);
      return ano * 12 + mes;
    }

    const automaticasAgrupadas = automaticas.map((e) => {
      const rotuloBase = formatarRotuloData(e.data);
      const ciclosDoDia = ciclosPorData.get(e.data);
      const ciclo = cicloPorEntradaAutomatica.get(e);

      if (!ciclo || !ciclosDoDia || ciclosDoDia.size < 2) {
        return { ...e, _grupoChave: e.data, _grupoRotulo: rotuloBase };
      }

      const ordenados = Array.from(ciclosDoDia).sort(
        (a, b) => ordemCronologicaChaveMesAno(a) - ordemCronologicaChaveMesAno(b)
      );
      const numeroCiclo = ordenados.indexOf(ciclo) + 1;

      return {
        ...e,
        _grupoChave: `${e.data}\u0000ciclo${ciclo}`,
        _grupoRotulo: `${rotuloBase} · ${t('cicloLabel')} ${numeroCiclo}`,
        _corteCiclo: true,
      };
    });

    for (let i = 1; i < automaticasAgrupadas.length; i++) {
      const atual = automaticasAgrupadas[i];
      const anterior = automaticasAgrupadas[i - 1];
      if (atual._grupoChave === anterior._grupoChave) continue;
      if (atual._corteCiclo) continue;
      const cicloAtual = chaveCicloDaEntrada(atual);
      const cicloAnterior = chaveCicloDaEntrada(anterior);
      if (cicloAtual && cicloAnterior && cicloAtual !== cicloAnterior) {
        atual._corteCiclo = true;
      }
    }

    if (manuais.length === 0) return automaticasAgrupadas;

    const manuaisAgrupadas = manuais.map((e) => ({
      ...e,
      _grupoChave: '\u0000manual',
      _grupoRotulo: t('categoriaManualLabel'),
    }));

    return [...automaticasAgrupadas, ...manuaisAgrupadas];
  }

  function fecharMenuOrdenacao() {
    document.querySelectorAll('#mxm-log-ordenacao-menu-overlay').forEach((el) => el.remove());
  }

  // Menu flutuante (mesmo padrão do menu de missão) com as 3 opções de
  // ordenação — aberto pelo botão de funil ao lado da primeira data.
  function abrirMenuOrdenacao(x, y) {
    fecharMenuOrdenacao();
    fecharMenuMissao();

    const overlay = document.createElement('div');
    overlay.id = 'mxm-log-ordenacao-menu-overlay';
    Object.assign(overlay.style, {
      position: 'fixed',
      inset: '0',
      zIndex: proximoZIndexFlutuante(),
    });
    overlay.addEventListener('click', fecharMenuOrdenacao);
    overlay.addEventListener('contextmenu', (e) => {
      e.preventDefault();
      fecharMenuOrdenacao();
    });

    const opcoes = [
      { valor: 'data', rotulo: t('ordenarPorData'), icone: 'calendar' },
      { valor: 'missao', rotulo: t('ordenarPorMissao'), icone: 'target' },
      { valor: 'alfabetica', rotulo: t('ordenarAlfabetica'), icone: 'hash' },
    ];
    const atual = getOrdenacaoLog();

    const menu = document.createElement('div');
    menu.style.cssText =
      'position:fixed; min-width:200px; background:var(--md-sys-color-surface-container-high); color:var(--md-sys-color-on-surface); border-radius:var(--md-shape-md); box-shadow:var(--md-elevation-3); padding:6px; font-family:sans-serif; font-size:12.5px;';
    menu.innerHTML = `
      <div style="padding:8px 10px 6px; font-size:10.5px; font-weight:700; letter-spacing:0.3px; text-transform:uppercase; color:var(--md-sys-color-outline);">${t(
        'ordenarFiltrarTitulo'
      )}</div>
      ${opcoes
        .map(
          (op) => `
        <div data-valor="${op.valor}" style="display:flex; align-items:center; gap:8px; padding:8px 10px; border-radius:var(--md-shape-sm); cursor:pointer; color:${
            op.valor === atual ? 'var(--md-sys-color-primary)' : 'var(--md-sys-color-on-surface)'
          }; background:${op.valor === atual ? 'color-mix(in srgb, var(--md-sys-color-primary) 12%, transparent)' : 'transparent'};">
          ${icone(op.icone, 14)}
          <span style="flex:1;">${op.rotulo}</span>
          ${op.valor === atual ? icone('check', 14) : ''}
        </div>
      `
        )
        .join('')}
    `;

    document.body.appendChild(overlay);
    overlay.appendChild(menu);

    // Posiciona perto do clique, sem sair da tela (mesma lógica simples
    // usada no menu de missão).
    const largura = 210;
    const altura = 6 + 30 + opcoes.length * 34;
    menu.style.left = `${Math.min(x, window.innerWidth - largura - 8)}px`;
    menu.style.top = `${Math.min(y, window.innerHeight - altura - 8)}px`;

    menu.querySelectorAll('[data-valor]').forEach((item) => {
      item.addEventListener('mouseenter', () => {
        if (item.getAttribute('data-valor') !== atual) item.style.background = 'var(--md-sys-color-surface-container-highest)';
      });
      item.addEventListener('mouseleave', () => {
        if (item.getAttribute('data-valor') !== atual) item.style.background = 'transparent';
      });
      item.addEventListener('click', (e) => {
        e.stopPropagation();
        setOrdenacaoLog(item.getAttribute('data-valor'));
        tocarSom('clique');
        fecharMenuOrdenacao();
        renderPainelLista();
      });
    });
  }

  // ---------- nome do curator (substitui o rótulo "Curator") ----------

  function getNomeCurator() {
    const salvo = localStorage.getItem(STORAGE_NOME_CURATOR_KEY);
    return salvo && salvo.trim() ? salvo.trim() : null;
  }

  function setNomeCurator(nome) {
    const limpo = (nome || '').trim();
    if (limpo) {
      localStorage.setItem(STORAGE_NOME_CURATOR_KEY, limpo);
    } else {
      localStorage.removeItem(STORAGE_NOME_CURATOR_KEY);
    }
    // pode ter completado a conquista "perfil customizado" (nome +
    // foto definidos) — ver calcularStatsConquistas.
    verificarNovasConquistas();
  }

  // ---------- selo de "verificado" (easter egg escondido) ----------

  function isSeloVerificadoAtivo() {
    return localStorage.getItem(STORAGE_SELO_VERIFICADO_KEY) === '1';
  }

  function setSeloVerificadoAtivo(ativo) {
    if (ativo) {
      localStorage.setItem(STORAGE_SELO_VERIFICADO_KEY, '1');
    } else {
      localStorage.removeItem(STORAGE_SELO_VERIFICADO_KEY);
    }
  }

  function iconeSeloVerificado(tamanho) {
    const t = tamanho || 14;
    // círculo simples com check branco — mais limpo e legível em
    // tamanho pequeno do que um contorno recortado (que "engorda"
    // visualmente e fica poluído nesse tamanho).
    return `<svg width="${t}" height="${t}" viewBox="0 0 20 20" style="display:block; flex-shrink:0;" aria-hidden="true">
      <circle cx="10" cy="10" r="10" fill="#4a99e9"/>
      <path fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" d="M5.5 10.3l2.7 2.7 6.3-6.5"/>
    </svg>`;
  }

  // contador do easter egg — vive só na memória (zera ao fechar/reabrir
  // o painel, ou depois de completar os 15 cliques), nunca é persistido.
  let contadorCliquesSeloVerificado = 0;

  // troca o selo já renderizado na hora, sem precisar re-renderizar o
  // painel inteiro (chamado depois do clique 15).
  function atualizarSeloVerificadoNoPainel() {
    const spanNome = document.getElementById('mxm-log-detalhado-nome-curator');
    if (!spanNome) return;
    let seloEl = document.getElementById('mxm-log-detalhado-selo-verificado');
    if (isSeloVerificadoAtivo()) {
      if (!seloEl) {
        seloEl = document.createElement('span');
        seloEl.id = 'mxm-log-detalhado-selo-verificado';
        seloEl.title = 'Verificado';
        seloEl.style.display = 'flex';
        seloEl.style.flexShrink = '0';
        spanNome.insertAdjacentElement('afterend', seloEl);
      }
      seloEl.innerHTML = iconeSeloVerificado(14);
    } else if (seloEl) {
      seloEl.remove();
    }
  }

  // liga o contador de cliques no título "Hoje vs Recorde" do Log
  // Detalhado — sem nenhuma pista visual, de propósito.
  function vincularCliqueSeloVerificado(elementoTitulo) {
    if (!elementoTitulo) return;
    elementoTitulo.style.cursor = 'default';
    elementoTitulo.addEventListener('click', () => {
      contadorCliquesSeloVerificado += 1;
      if (contadorCliquesSeloVerificado >= 15) {
        contadorCliquesSeloVerificado = 0;
        setSeloVerificadoAtivo(!isSeloVerificadoAtivo());
        tocarSom(isSeloVerificadoAtivo() ? 'sucesso' : 'clique');
        atualizarSeloVerificadoNoPainel();
      }
    });
  }

  // ---------- foto de perfil e capa customizadas (painel de log detalhado) ----------
  function normalizarValorRecorte(bruto) {
    if (!bruto) return null;
    if (typeof bruto !== 'string') return null;
    if (bruto.startsWith('data:')) {
      return { url: bruto, zoomPct: 100, xPct: 50, yPct: 50 };
    }
    try {
      const obj = JSON.parse(bruto);
      if (obj && typeof obj.url === 'string') {
        return {
          url: obj.url,
          zoomPct: Number.isFinite(obj.zoomPct) ? obj.zoomPct : 100,
          xPct: Number.isFinite(obj.xPct) ? obj.xPct : 50,
          yPct: Number.isFinite(obj.yPct) ? obj.yPct : 50,
        };
      }
    } catch (e) {
      // não era JSON nem data URL — ignora, trata como se não houvesse nada salvo
    }
    return null;
  }

  // usado pelo editor de recorte pra manter xPct/yPct sempre entre
  // 0 e 100 enquanto o usuário arrasta a imagem.
  function clampNumero(valor, min, max) {
    return Math.min(Math.max(valor, min), max);
  }

  // Monta o fragmento de CSS que reproduz um valor de recorte — usado tanto
  // no preview do editor quanto na exibição final (foto e capa).
  function estiloFundoRecorte(valor) {
    if (!valor) return '';
    const url = String(valor.url).replace(/'/g, '%27').replace(/"/g, '%22');
    return `background-image:url('${url}'); background-repeat:no-repeat; background-size:${valor.zoomPct}% auto; background-position:${valor.xPct}% ${valor.yPct}%;`;
  }

  function getFotoCuratorCustom() {
    return normalizarValorRecorte(localStorage.getItem(STORAGE_FOTO_CURATOR_KEY));
  }

  function setFotoCuratorCustom(valor) {
    localStorage.setItem(STORAGE_FOTO_CURATOR_KEY, JSON.stringify(valor));
    // pode ter completado a conquista "perfil customizado" (nome +
    // foto definidos) — ver calcularStatsConquistas.
    verificarNovasConquistas();
  }

  function limparFotoCuratorCustom() {
    localStorage.removeItem(STORAGE_FOTO_CURATOR_KEY);
  }

  // capa/banner customizada — mesmo esquema de valor/armazenamento
  // da foto acima, só que sem nenhuma "padrão" pra cair de volta (ver
  // comentário na declaração de STORAGE_CAPA_CURATOR_KEY).
  function getCapaCuratorCustom() {
    return normalizarValorRecorte(localStorage.getItem(STORAGE_CAPA_CURATOR_KEY));
  }

  function setCapaCuratorCustom(valor) {
    localStorage.setItem(STORAGE_CAPA_CURATOR_KEY, JSON.stringify(valor));
  }

  function limparCapaCuratorCustom() {
    localStorage.removeItem(STORAGE_CAPA_CURATOR_KEY);
  }

  const LIMITE_IMAGEM_RECORTE_BYTES = 8 * 1024 * 1024; // 8MB

  function carregarDimensoesImagem(url) {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.onerror = () => reject(new Error('imagem inválida'));
      img.onload = () => resolve({ url, naturalWidth: img.naturalWidth, naturalHeight: img.naturalHeight });
      img.src = url;
    });
  }

  function processarImagemEscolhida(arquivo) {
    return new Promise((resolve, reject) => {
      if (!arquivo || !arquivo.type || !arquivo.type.startsWith('image/')) {
        reject(new Error('tipo inválido'));
        return;
      }
      if (arquivo.size > LIMITE_IMAGEM_RECORTE_BYTES) {
        reject(new Error('arquivo grande demais'));
        return;
      }
      const isGif = arquivo.type === 'image/gif';
      const leitor = new FileReader();
      leitor.onerror = () => reject(new Error('leitura falhou'));
      leitor.onload = () => {
        const img = new Image();
        img.onerror = () => reject(new Error('imagem inválida'));
        img.onload = () => {
          if (isGif) {
            resolve({ url: leitor.result, isGif: true, naturalWidth: img.naturalWidth, naturalHeight: img.naturalHeight });
            return;
          }
          const MAX_LADO = 1000;
          const maiorLado = Math.max(img.naturalWidth, img.naturalHeight);
          const escala = maiorLado > MAX_LADO ? MAX_LADO / maiorLado : 1;
          const largura = Math.max(1, Math.round(img.naturalWidth * escala));
          const altura = Math.max(1, Math.round(img.naturalHeight * escala));

          const canvas = document.createElement('canvas');
          canvas.width = largura;
          canvas.height = altura;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(img, 0, 0, largura, altura);

          resolve({ url: canvas.toDataURL('image/jpeg', 0.88), isGif: false, naturalWidth: largura, naturalHeight: altura });
        };
        img.src = leitor.result;
      };
      leitor.readAsDataURL(arquivo);
    });
  }

