  function converterParaTemaClaro(chaveDestaque, chaveFundo) {
    return {
      d: MXM_ESQUEMAS_DESTAQUE_CLARO[chaveDestaque] || MXM_ESQUEMAS_DESTAQUE_CLARO.roxo,
      f: MXM_ESQUEMAS_FUNDO_CLARO[chaveFundo] || MXM_ESQUEMAS_FUNDO_CLARO.neutro,
    };
  }

  // atualiza o ícone de sol/lua no cabeçalho pra refletir o modo atual,
  // sempre que existir (o painel pode não estar aberto no momento).
  function atualizarIconeTemaClaro() {
    const btn = document.getElementById('mxm-log-tema-claro-btn');
    if (!btn) return;
    const ativo = isTemaClaroAtivo();
    btn.innerHTML = icone(ativo ? 'moon' : 'sun', 16);
    btn.title = ativo ? t('voltarTemaEscuro') : t('ativarTemaClaro');
  }

