      background: '#1a1112', onBackground: '#f0dedf', surface: '#1a1112', onSurface: '#f0dedf',
      surfaceVariant: '#554244', onSurfaceVariant: '#dac0c2', outline: '#a28b8d', outlineVariant: '#554244',
      inverseSurface: '#f0dedf', inverseOnSurface: '#382e2f',
